// Embedded WOFF2 Fonts for self-contained SVG & Canvas rendering
export const FONTCSS = "@font-face{font-family:'Montserrat';font-weight:500;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Montserrat';font-weight:700;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Montserrat';font-weight:800;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Pirata One';font-weight:400;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Playfair Display';font-weight:900;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Bebas Neue';font-weight:400;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Special Elite';font-weight:400;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}";

export function injectFonts() {
  if (typeof document !== "undefined" && document.head && !document.getElementById("embedded-ticket-fonts")) {
    const style = document.createElement("style");
    style.id = "embedded-ticket-fonts";
    style.textContent = FONTCSS;
    document.head.appendChild(style);
  }
}
